stancia.\nPotencia 6"},{"nombre":"Juicio de Selene","descripcion":"Desata el Juicio de Selene sobre los objetivos cercanos e inflige daño masivo, evoluciona a fennelun y aumenta su daño en un 15 % hasta que termine el combate. También obtiene 4 acumulaciones de Marca de luna plateada.\nPotencia 167"}],"atributos":[]},{"categoria":"Movilidad","icono":"https://worldx-website-cdn.aniimo.com/official-website/worldx/wiki_stage/init/1036100_Skill_9400107_Icon.png","tecnicas":[{"nombre":"Ajetreo","descripcion":"Entra en el estado Ajetreo, lo que aumenta la velocidad de movimiento al consumir vigor."}],"atributos":[]}],"materiales":[]}'::jsonb, null, '{"total":514,"valores":[{"campo":"PV","valor":100},{"campo":"ATQ","valor":116},{"campo":"RUPT.","valor":64},{"campo":"DEF F.","valor":72},{"campo":"DEF M.","valor":72},{"campo":"REGEN.","valor":90}]}'::jsonb, null),
