on conflict (id) do update
  set game_id = excluded.game_id,
      name = excluded.name,
      image_url = excluded.image_url,
      element = excluded.element,
      role = excluded.role,
      path = excluded.path,
      signature = excluded.signature,
      description = excluded.description,
      biography_es = excluded.biography_es,
      biography_source_es = excluded.biography_source_es,
      profile = excluded.profile,
      skills = excluded.skills,
      evolution = excluded.evolution,
      stats = excluded.stats,
      habitats = excluded.habitats;

-- Comprobacion
select element, count(*) as criaturas, count(skills) as con_habilidades, count(evolution) as con_evolucion
from public.characters
where game_id = 'aniimo'
group by element
order by element;
